package com.metaplatform.agent.events;
import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest; import org.springframework.test.context.TestPropertySource; import java.time.Instant; import static org.assertj.core.api.Assertions.assertThat;
@DataJpaTest @TestPropertySource(properties={"spring.flyway.enabled=false","spring.jpa.hibernate.ddl-auto=create-drop"}) class RunEventRepositoryTest { @Autowired RunEventRepository repository; @Test void crudAndCustomQueries(){ repository.save(RunEventEntity.builder().eventId("event-1").runId("run-1").type(RunEventType.RUN_STARTED).ts(Instant.now()).traceId("tr").tenantId("t").payload("{}").seq(1L).build()); assertThat(repository.findById("event-1")).isPresent(); assertThat(repository.findByEventId("event-1")).isPresent(); assertThat(repository.findByRunIdOrderBySeqAsc("run-1")).hasSize(1); assertThat(repository.findByRunIdAndSeqGreaterThanOrderBySeqAsc("run-1",0L)).hasSize(1); } }
